WITH session_paths AS (WITH paths_deduped_cte AS (WITH ordered_events AS (SELECT session_id, concat(origin, path) as path, created_at FROM events WHERE project_id = {p1:String} AND name = {p2:String} AND path != {p3:String} AND path IS NOT NULL AND created_at BETWEEN toDateTime({p4:String}) AND toDateTime({p5:String}) ORDER BY session_id ASC, created_at ASC) SELECT session_id, arraySlice(
          arrayFilter(
            (x, i) -> i = {p6:Int64} OR x != paths_raw[i - {p7:Int64}],
            groupArray(path) as paths_raw,
            arrayEnumerate(paths_raw)
          ),
          {p8:Int64}, {p9:Int64}
        ) as paths_deduped FROM ordered_events GROUP BY session_id) SELECT session_id, if(
          arrayFirstIndex(x -> x > {p10:Int64}, arrayEnumerateUniq(paths_deduped)) = {p11:Int64},
          paths_deduped,
          arraySlice(
            paths_deduped,
            {p12:Int64},
            arrayFirstIndex(x -> x > {p13:Int64}, arrayEnumerateUniq(paths_deduped)) - {p14:Int64}
          )
        ) as paths, paths[{p15:Int64}] as entry_page FROM paths_deduped_cte HAVING length(paths) >= {p16:Int64}) SELECT entry_page, count() as count FROM session_paths GROUP BY entry_page ORDER BY count DESC LIMIT {p17:Int64} 
FORMAT JSON

