WITH session_paths AS (WITH start_event_sessions AS (SELECT session_id FROM events WHERE project_id = {p1:String} AND name = {p2:String} AND created_at BETWEEN toDateTime({p3:String}) AND toDateTime({p4:String}) GROUP BY session_id), events_deduped_cte AS (WITH ordered_events AS (SELECT session_id, name as event_name, created_at FROM events WHERE project_id = {p5:String} AND created_at BETWEEN toDateTime({p6:String}) AND toDateTime({p7:String}) ORDER BY session_id ASC, created_at ASC) SELECT session_id, arrayFilter(
          (x, i) -> i = {p8:Int64} OR x != events_raw[i - {p9:Int64}],
          groupArray(event_name) as events_raw,
          arrayEnumerate(events_raw)
        ) as events_deduped FROM ordered_events GROUP BY session_id), events_sliced_cte AS (SELECT session_id, arraySlice(events_deduped, arrayFirstIndex(x -> x = {p10:String}, events_deduped), {p11:Int64}) as events_sliced FROM events_deduped_cte HAVING session_id IN (SELECT session_id FROM start_event_sessions)) SELECT session_id, if(
      arrayFirstIndex(x -> x > {p12:Int64}, arrayEnumerateUniq(events_sliced)) = {p13:Int64},
      events_sliced,
      arraySlice(
        events_sliced,
        {p14:Int64},
        arrayFirstIndex(x -> x > {p15:Int64}, arrayEnumerateUniq(events_sliced)) - {p16:Int64}
      )
    ) as events, events[{p17:Int64}] as entry_event FROM events_sliced_cte HAVING length(events) >= {p18:Int64}) SELECT entry_event, count() as count FROM session_paths GROUP BY entry_event ORDER BY count DESC LIMIT {p19:Int64} 
FORMAT JSON

