WITH paths_deduped_cte AS (WITH ordered_events AS (SELECT session_id, concat(origin, path) as path, created_at FROM events WHERE project_id = {p1:String} AND name = {p2:String} AND path != {p3:String} AND path IS NOT NULL AND created_at BETWEEN toDateTime({p4:String}) AND toDateTime({p5:String}) ORDER BY session_id ASC, created_at ASC) SELECT session_id, arraySlice(
          arrayFilter(
            (x, i) -> i = {p6:Int64} OR x != paths_raw[i - {p7:Int64}],
            groupArray(path) as paths_raw,
            arrayEnumerate(paths_raw)
          ),
          {p8:Int64}, {p9:Int64}
        ) as paths_deduped FROM ordered_events GROUP BY session_id), session_paths AS (SELECT session_id, if(
              arrayFirstIndex(x -> x > {p10:Int64}, arrayEnumerateUniq(paths_deduped)) = {p11:Int64},
              paths_deduped,
              arraySlice(
                paths_deduped,
                {p12:Int64},
                arrayFirstIndex(x -> x > {p13:Int64}, arrayEnumerateUniq(paths_deduped)) - {p14:Int64}
              )
            ) as paths FROM paths_deduped_cte HAVING length(paths) >= {p15:Int64} AND paths[{p16:Int64}] IN ({p17:String})) SELECT pair.1 as source, pair.2 as target, pair.3 as step, count() as value FROM ((SELECT arrayJoin(arrayMap(i -> (paths[i], paths[i + {p18:Int64}], i), range({p19:Int64}, length(paths)))) as pair FROM session_paths WHERE length(paths) >= {p20:Int64})) GROUP BY source, target, step ORDER BY step ASC, value DESC 
FORMAT JSON

q:bf6b23ca-e23d-4dea-aca7-5f79fa8f3209.query:
WITH profileSeen AS (
      SELECT created_at as firstSeen, last_seen_at as lastSeen
      FROM profiles FINAL
      WHERE id = {p1:String} AND project_id = {p2:String}
      LIMIT {p3:Int64}
    ),
    screenViews AS (
      SELECT count(*) as screenViews FROM events WHERE name = {p4:String} AND profile_id = {p5:String} AND project_id = {p6:String}
    ),
    sessions AS (
      SELECT count(*) as sessions FROM events WHERE name = {p7:String} AND profile_id = {p8:String} AND project_id = {p9:String}
    ),
    duration AS (
      SELECT 
        round(avg(duration) / {p10:Int64} / {p11:Int64}, {p12:Int64}) as durationAvg, 
        round(quantilesExactInclusive({p13:Float64})(duration)[{p14:Int64}] / {p15:Int64} / {p16:Int64}, {p17:Int64}) as durationP90 
      FROM events 
      WHERE name = {p18:String} AND duration != {p19:Int64} AND profile_id = {p20:String} AND project_id = {p21:String}
    ),
    totalEvents AS (
      SELECT count(*) as totalEvents FROM events WHERE profile_id = {p22:String} AND project_id = {p23:String}
    ),
    uniqueDaysActive AS (
      SELECT count(DISTINCT toDate(created_at)) as uniqueDaysActive FROM events WHERE profile_id = {p24:String} AND project_id = {p25:String}
    ),
    bounceRate AS (
      SELECT round(avg(properties[{p26:String}] = {p27:String}) * {p28:Int64}, {p29:Int64}) as bounceRate FROM events WHERE name = {p30:String} AND profile_id = {p31:String} AND project_id = {p32:String}
    ),
    avgEventsPerSession AS (
      SELECT round((SELECT totalEvents FROM totalEvents) / nullIf((SELECT sessions FROM sessions), {p33:Int64}), {p34:Int64}) as avgEventsPerSession
    ),
    conversionEvents AS (
      SELECT count(*) as conversionEvents FROM events WHERE name NOT IN ({p35:String}, {p36:String}, {p37:String}) AND profile_id = {p38:String} AND project_id = {p39:String}
    ),
    avgTimeBetweenSessions AS (
      SELECT 
        CASE 
          WHEN (SELECT sessions FROM sessions) <= {p40:Int64} THEN {p41:Int64}
          ELSE round(dateDiff({p42:String}, (SELECT firstSeen FROM profileSeen), (SELECT lastSeen FROM profileSeen)) / nullIf((SELECT sessions FROM sessions) - {p43:Int64}, {p44:Int64}), {p45:Int64})
        END as avgTimeBetweenSessions
    ),
    revenue AS (
      SELECT sum(revenue) as revenue FROM events WHERE name = {p46:String} AND profile_id = {p47:String} AND project_id = {p48:String}
    )
    SELECT 
      (SELECT lastSeen FROM profileSeen) as lastSeen,
      (SELECT firstSeen FROM profileSeen) as firstSeen,
      (SELECT screenViews FROM screenViews) as screenViews, 
      (SELECT sessions FROM sessions) as sessions, 
      (SELECT durationAvg FROM duration) as durationAvg, 
      (SELECT durationP90 FROM duration) as durationP90,
      (SELECT totalEvents FROM totalEvents) as totalEvents,
      (SELECT uniqueDaysActive FROM uniqueDaysActive) as uniqueDaysActive,
      (SELECT bounceRate FROM bounceRate) as bounceRate,
      (SELECT avgEventsPerSession FROM avgEventsPerSession) as avgEventsPerSession,
      (SELECT conversionEvents FROM conversionEvents) as conversionEvents,
      (SELECT avgTimeBetweenSessions FROM avgTimeBetweenSessions) as avgTimeBetweenSessions,
      (SELECT revenue FROM revenue) as revenue 
FORMAT JSON
